INSERT INTO "Announcement" ("id","title","category","summary","content","authorName","isPinned","isNew","isUrgent","attachments","coverColor","datePublished","createdAt","updatedAt") VALUES ('ann000000000000000000000001', 'Pengumuman Hari Kebangsaan PERKESO 2026', 'Korporat', 'Sambutan Hari Kebangsaan akan diadakan di semua cawangan PERKESO seluruh negara pada 31 Ogos 2026.', 'Bersempena sambutan Hari Kebangsaan ke-59, PERKESO akan mengadakan pelbagai aktiviti korporat di semua cawangan. Semua kakitangan dijemput menyertai perhimpunan dan acara budaya. Sila hadir berpakaian tradisional atau pakaian bertema ''Merdeka''. Majlis akan bermula jam 8:00 pagi.', 'Aisyah Binti Rahman', true, true, false, '[{"name":"Program_Merdeka_2026.pdf","type":"PDF","size":"1.2 MB"},{"name":"Senarai_Activiti.docx","type":"DOCX","size":"680 KB"}]', '#ED1C24', '2026-07-25T09:00:00Z', NOW(), NOW());
INSERT INTO "Announcement" ("id","title","category","summary","content","authorName","isPinned","isNew","isUrgent","attachments","coverColor","datePublished","createdAt","updatedAt") VALUES ('ann000000000000000000000002', 'Kemas Kini Sistem Caruman Bulanan PERKESO', 'ICT', 'Sistem caruman bulanan telah dinaik taraf dengan ciri e-pengesahan dan laporan pantas.', 'Sistem Pengurusan Caruman Bulanan (SPCB) versi 3.2 telah dilancarkan secara rasmi. Ciri baharu termasuk e-pengesahan dokumen, janaan laporan masa nyata, dan integrasi pejabat pos cawangan. Latihan pengguna akan diadakan setiap Khamis jam 2:00 petang secara dalam talian.', 'Nurul Huda Binti Aziz', false, true, false, '[{"name":"Manual_SPCB_v3.2.pdf","type":"PDF","size":"3.4 MB"}]', '#007DC5', '2026-07-22T14:30:00Z', NOW(), NOW());
INSERT INTO "Announcement" ("id","title","category","summary","content","authorName","isPinned","isNew","isUrgent","attachments","coverColor","datePublished","createdAt","updatedAt") VALUES ('ann000000000000000000000003', 'Cutian Umum Hari Buruh — Klinik Tutup', 'HR', 'Klinik PERKESO akan ditutup pada 1 Mei 2026 bersempena Hari Buruh.', 'Dimaklumkan bahawa semua klinik PERKESO di seluruh negara akan tutup pada 1 Mei 2026 (Hari Buruh). Rawatan kecemasan boleh dirujuk ke panel klinik berdekatan. Operasi akan kembali normal pada 2 Mei 2026.', 'Aisyah Binti Rahman', false, true, false, '[]', '#8DC63E', '2026-07-20T08:00:00Z', NOW(), NOW());
INSERT INTO "Announcement" ("id","title","category","summary","content","authorName","isPinned","isNew","isUrgent","attachments","coverColor","datePublished","createdAt","updatedAt") VALUES ('ann000000000000000000000004', 'AMARAN: Phishing E-mel Berpura-pura PERKESO', 'Kesihatan & Keselamatan', 'Dimaklumkan terdapat e-mel phishing yang berpura-pura dari PERKESO. Jangan klik pautan.', 'Pihak ICT telah menerima laporan bahawa terdapat e-mel phishing yang berpura-pura daripada PERKESO meminta maklumat log masuk. JANGAN klik sebarang pautan atau berikan maklumat peribadi. Laporkan segera ke soc@perkeso.gov.my. PERKESO tidak akan meminta kata laluan melalui e-mel.', 'Ravi Kumar a/l Subramaniam', true, true, true, '[{"name":"Panduan_Keselamatan.pdf","type":"PDF","size":"920 KB"}]', '#ED1C24', '2026-07-19T10:15:00Z', NOW(), NOW());
INSERT INTO "Announcement" ("id","title","category","summary","content","authorName","isPinned","isNew","isUrgent","attachments","coverColor","datePublished","createdAt","updatedAt") VALUES ('ann000000000000000000000005', 'Pertandingan Inovasi Kakitangan 2026', 'Korporat', 'Pendaftaran pertandingan inovasi kakitangan telah dibuka. Hadiah RM10,000.', 'PERKESO mengumumkan pertandingan inovasi kakitangan 2026 dengan tema ''Inovasi Untuk Rakyat''. Pendaftaran dibuka sehingga 15 Ogos 2026. Hadiah utama RM10,000 dan trofi. Penilaian berdasarkan kebolehgunaan, keberkesanan, dan impak operasi.', 'Nurul Huda Binti Aziz', false, false, false, '[{"name":"Borang_Penyertaan.docx","type":"DOCX","size":"420 KB"}]', '#F9BF10', '2026-07-10T09:00:00Z', NOW(), NOW());
INSERT INTO "Announcement" ("id","title","category","summary","content","authorName","isPinned","isNew","isUrgent","attachments","coverColor","datePublished","createdAt","updatedAt") VALUES ('ann000000000000000000000006', 'Kemas Kini Prosedur Tuntutan Pampasan Pekerja', 'Operasi', 'Prosedur tuntutan pampasan pekerja dikemas kini bagi mempercepat proses pengesahan.', 'Bermula 1 Ogos 2026, prosedur tuntutan pampasan pekerja akan dikemas kini dengan pengurangan masa pengesahan daripada 14 hari kepada 7 hari kerja. Borang baharu boleh dimuat turun dari modul SOP.', 'Mohammad Faizal Bin Osman', false, false, false, '[{"name":"Borang_Pampasan_v2.pdf","type":"PDF","size":"1.8 MB"}]', '#00C5AB', '2026-07-05T11:00:00Z', NOW(), NOW());
INSERT INTO "Announcement" ("id","title","category","summary","content","authorName","isPinned","isNew","isUrgent","attachments","coverColor","datePublished","createdAt","updatedAt") VALUES ('ann000000000000000000000007', 'Latihan Kesedaran Siber Keselamatan Wajib', 'Kesihatan & Keselamatan', 'Semua kakitangan diwajibkan hadir latihan kesedaran siber keselamatan.', 'Pihak pengurusan menetapkan bahawa semua kakitangan PERKESO wajib menghadiri latihan kesedaran siber keselamatan yang akan diadakan secara dalam talian. Slot boleh dipilih melalui portal latihan dalaman.', 'Ravi Kumar a/l Subramaniam', false, false, false, '[]', '#F27130', '2026-06-28T08:00:00Z', NOW(), NOW());
INSERT INTO "Announcement" ("id","title","category","summary","content","authorName","isPinned","isNew","isUrgent","attachments","coverColor","datePublished","createdAt","updatedAt") VALUES ('ann000000000000000000000008', 'Program Pensijilan ISO 27001 — Fasa 2', 'Korporat', 'PERKESO meneruskan program pensijilan ISO 27001 dengan audit fasa 2 pada September 2026.', 'Bahagian Kualiti & Keselamatan Maklumat akan menjalankan audit ISO 27001 fasa 2 pada September 2026. Semua jabatan diminta menyemak dan mengemaskini SOP berkaitan keselamatan maklumat sebelum 15 Ogos 2026.', 'Aisyah Binti Rahman', false, false, false, '[{"name":"Senarai_Semak_ISO27001.xlsx","type":"XLSX","size":"240 KB"}]', '#004E7A', '2026-06-20T09:30:00Z', NOW(), NOW());
