INSERT INTO "Act" ("id","actNumber","title","category","description","fileName","fileSize","version","status","lastUpdated","createdAt","updatedAt") VALUES ('act000000000000000000000002', 'Akta 799', 'Akta Sistem Insurans Pekerjaan 2017', 'Akta Insurans', 'Mewujudkan skim insurans pekerjaan bagi menganugerahkan faedah kepada pekerja yang mengalami kemalangan kerja atau penyakit pekerjaan.', 'Akta_799_2017.pdf', '3.2 MB', 'Edisi 2025', 'Aktif', '2026-05-20T12:00:00Z', NOW(), NOW());
INSERT INTO "Act" ("id","actNumber","title","category","description","fileName","fileSize","version","status","lastUpdated","createdAt","updatedAt") VALUES ('act000000000000000000000003', 'Akta 800', 'Akta Sistem Insurans Pekerjaan (Peraturan) 2017', 'Akta Insurans', 'Peraturan pelaksanaan Akta Sistem Insurans Pekerjaan 2017 mengenai tatacara pengurusan tuntutan dan pembayaran faedah.', 'Akta_800_2017.pdf', '1.6 MB', 'Edisi 2025', 'Aktif', '2026-04-12T09:00:00Z', NOW(), NOW());
INSERT INTO "Act" ("id","actNumber","title","category","description","fileName","fileSize","version","status","lastUpdated","createdAt","updatedAt") VALUES ('act000000000000000000000004', 'Akta 514', 'Akta Keselamatan dan Kesihatan Pekerjaan 1994', 'Akta Sosial', 'Mewujudkan rangka kerja perundangan bagi memastikan keselamatan, kesihatan, dan kebajikan pekerja di tempat kerja.', 'Akta_514_1994.pdf', '2.4 MB', 'Edisi 2024', 'Digantungan', '2025-11-10T10:00:00Z', NOW(), NOW());
