INSERT INTO "Act" ("id","actNumber","title","category","description","fileName","fileSize","version","status","lastUpdated","createdAt","updatedAt") VALUES ('act000000000000000000000006', 'Akta 139', 'Akta Kerja 1955', 'Peraturan', 'Akta yang mengawal selia hubungan majikan-pekerja, termasuk waktu kerja, cuti, dan upah.', 'Akta_139_1955.pdf', '3.8 MB', 'Edisi 2026 (Pindaan)', 'Aktif', '2026-01-25T08:00:00Z', NOW(), NOW());
INSERT INTO "Act" ("id","actNumber","title","category","description","fileName","fileSize","version","status","lastUpdated","createdAt","updatedAt") VALUES ('act000000000000000000000007', 'Akta 827', 'Akta Perlindungan Data Peribadi 2010', 'Peraturan', 'Mengawal pemprosesan data peribadi individu dan hak individu terhadap data peribadinya.', 'Akta_827_2010.pdf', '1.4 MB', 'Edisi 2024', 'Aktif', '2025-12-10T09:00:00Z', NOW(), NOW());
