INSERT INTO "Asip" ("id","title","referenceNo","description","effectiveDate","fileName","fileSize","status","category","createdAt","updatedAt") VALUES ('asp000000000000000000000001', 'Skim Insurans Pekerjaan — Pampasan Kemalangan', 'ASIP/PK/001/2026', 'Skim pampasan kemalangan kerja bagi pekerja yang mengalami kecederaan dalam masa dan di tempat kerja.', '2026-01-01T00:00:00Z', 'ASIP_Pampasan_Kemalangan.pdf', '1.6 MB', 'Aktif', 'Pampasan', NOW(), NOW());
INSERT INTO "Asip" ("id","title","referenceNo","description","effectiveDate","fileName","fileSize","status","category","createdAt","updatedAt") VALUES ('asp000000000000000000000002', 'Skim Insurans Pekerjaan — Pencen Ilat', 'ASIP/PI/002/2026', 'Skim pencen ilat bagi pekerja yang mengalami kecacatan kekal akibat kemalangan kerja.', '2026-01-01T00:00:00Z', 'ASIP_Pencen_Ilat.pdf', '1.4 MB', 'Aktif', 'Pencen', NOW(), NOW());
INSERT INTO "Asip" ("id","title","referenceNo","description","effectiveDate","fileName","fileSize","status","category","createdAt","updatedAt") VALUES ('asp000000000000000000000003', 'Skim Insurans Pekerjaan — Pencematian', 'ASIP/PM/003/2025', 'Manfaat kematian kepada tanggungan pekerja yang meninggal dunia akibat kemalangan kerja.', '2025-06-01T00:00:00Z', 'ASIP_Pencematian.pdf', '1.1 MB', 'Aktif', 'Manfaat Kematian', NOW(), NOW());
INSERT INTO "Asip" ("id","title","referenceNo","description","effectiveDate","fileName","fileSize","status","category","createdAt","updatedAt") VALUES ('asp000000000000000000000004', 'Skim Insurans Pekerjaan — Bayaran Perubatan', 'ASIP/BP/004/2026', 'Pembayaran perubatan bagi rawatan berkaitan kemalangan kerja atau penyakit pekerjaan.', '2026-01-15T00:00:00Z', 'ASIP_Bayaran_Perubatan.pdf', '2.2 MB', 'Aktif', 'Perubatan', NOW(), NOW());
INSERT INTO "Asip" ("id","title","referenceNo","description","effectiveDate","fileName","fileSize","status","category","createdAt","updatedAt") VALUES ('asp000000000000000000000005', 'Skim Insurans Pekerjaan — Pemulihan Fizio', 'ASIP/PF/005/2025', 'Program pemulihan fizio dan vokasional bagi pekerja yang mengalami kecederaan kerja.', '2025-03-01T00:00:00Z', 'ASIP_Pemulihan.pdf', '1.8 MB', 'Digantikan', 'Pemulihan', NOW(), NOW());
INSERT INTO "Asip" ("id","title","referenceNo","description","effectiveDate","fileName","fileSize","status","category","createdAt","updatedAt") VALUES ('asp000000000000000000000006', 'Skim Insurans Pekerjaan — Faedah Hari Tidak Bekerja', 'ASIP/HTB/006/2026', 'Bayaran ganti bagi hari tidak bekerja akibat cuti sakit berkaitan kemalangan kerja.', '2026-02-01T00:00:00Z', 'ASIP_HTB.pdf', '950 KB', 'Dalam Semakan', 'Bayaran Ganti', NOW(), NOW());
INSERT INTO "Sop" ("id","title","department","description","procedureSteps","fileName","fileSize","version","approvedBy","dateApproved","status","createdAt","updatedAt") VALUES ('sop000000000000000000000001', 'SOP Tuntutan Pampasan Pekerja', 'Pampasan', 'Prosedur standard pengendalian tuntutan pampasan pekerja berkaitan kemalangan kerja.', '["Pekerja melaporkan kemalangan kepada majikan dalam masa 48 jam.","Majikan mengemukakan borang laporan kemalangan (Borang 21) ke cawangan PERKESO.","Pegawai pampasan menyemak dokumen dan mengeluarkan nombor rujukan tuntutan.","Pemeriksaan perubatan dijalankan oleh panel klinik PERKESO.","Pengesahan tahap kecederaan oleh Lembaga Perubatan.","Keputusan tuntutan dikeluarkan dalam masa 7 hari kerja selepas lengkap dokumen.","Bayaran pampasan diproses dan dikredit ke akaun pekerja dalam 14 hari."]', 'SOP_Pampasan_v2.pdf', '1.2 MB', '2.0', 'Timbalan Pengarah Bahagian Pampasan', '2026-06-20T10:00:00Z', 'Aktif', NOW(), NOW());
INSERT INTO "Sop" ("id","title","department","description","procedureSteps","fileName","fileSize","version","approvedBy","dateApproved","status","createdAt","updatedAt") VALUES ('sop000000000000000000000002', 'SOP Pengurusan Rekod Perubatan', 'Perubatan', 'Pengurusan, penyimpanan, dan pemusnahan rekod perubatan pesakit PERKESO.', '["Semua rekod perubatan direkod dalam Sistem Pengurusan Rekod Perubatan (SPRP).","Rekod fizikal disimpan di ruang arkib berkontrol akses.","Akses kepada rekod terhad kepada pegawai perubatan dan pesakit sahaja.","Rekod disimpan sekurang-kurangnya 7 tahun sebelum dimusnah.","Pemusnahan rekod direkod dalam log pemusnahan dan ditandatangani oleh Pegawai Perubatan Kanan."]', 'SOP_Rekod_Perubatan.pdf', '880 KB', '1.5', 'Pengarah Bahagian Perubatan', '2026-05-10T09:00:00Z', 'Aktif', NOW(), NOW());
INSERT INTO "Sop" ("id","title","department","description","procedureSteps","fileName","fileSize","version","approvedBy","dateApproved","status","createdAt","updatedAt") VALUES ('sop000000000000000000000003', 'SOP Pengesahan Invois Pembekal', 'Kewangan', 'Proses pengesahan dan bayaran invois pembekal PERKESO.', '["Pembekal menghantar invois melalui portal e-Procurement.","Pegawai kewangan menyemak kesahihan dan ketepatan maklumat.","Pegawai kewangan menyemak LPO / kontrak berkaitan.","Pengesahan oleh Ketua Bahagian Kewangan.","Bayaran diproses melalui sistem Gaji & Bayaran (SGB).","Invois ditandai sebagai ''Dibayar'' dalam sistem."]', 'SOP_Invois_Pembekal.pdf', '640 KB', '1.8', 'Pengarah Bahagian Kewangan', '2026-04-15T14:00:00Z', 'Aktif', NOW(), NOW());
INSERT INTO "Sop" ("id","title","department","description","procedureSteps","fileName","fileSize","version","approvedBy","dateApproved","status","createdAt","updatedAt") VALUES ('sop000000000000000000000004', 'SOP Pengurusan Aset ICT', 'ICT', 'Pengurusan kitar hayat aset teknologi maklumat PERKESO.', '["Pendaftaran aset ICT dalam Sistem Pengurusan Aset (SPA) dengan kod unik.","Pelabelan aset dengan nombor siri dan kod inventori.","Pengedaran aset direkod dengan penerima dan lokasi.","Penyenggaraan berkala mengikut jadual tahunan.","Pelupusan aset melalui lelongan / sumbangan dengan kebenaran Lembaga."]', 'SOP_Aset_ICT.pdf', '1.1 MB', '1.2', 'Pengarah Bahagian ICT', '2026-03-08T11:00:00Z', 'Aktif', NOW(), NOW());
INSERT INTO "Sop" ("id","title","department","description","procedureSteps","fileName","fileSize","version","approvedBy","dateApproved","status","createdAt","updatedAt") VALUES ('sop000000000000000000000005', 'SOP Pengambilan Kakitangan Baharu', 'HR', 'Proses pengambilan dan orientasi kakitangan baru PERKESO.', '["Pengiklanan jawatan kosong di portal kerjaya PERKESO.","Penapisan permohonan oleh sistem dan pegawai HR.","Temu duga oleh panel (HR + ketua jabatan).","Pengesahan latar belakang dan pemeriksaan perubatan.","Tawaran jawatan dan penerimaan oleh calon.","Orientasi 3 hari di Ibu Pejabat dan penyerahan kad pengguna."]', 'SOP_Pengambilan_HR.pdf', '780 KB', '2.1', 'Pengarah Bahagian HR', '2026-02-25T09:30:00Z', 'Aktif', NOW(), NOW());
INSERT INTO "Sop" ("id","title","department","description","procedureSteps","fileName","fileSize","version","approvedBy","dateApproved","status","createdAt","updatedAt") VALUES ('sop000000000000000000000006', 'SOP Pengurusan Operasi Cawangan', 'Operasi', 'Prosedur pengurusan operasi harian cawangan PERKESO.', '["Buka cawangan jam 8:00 pagi dan semak sistem POS & LAN.","Pengasingan kaunter mengikut perkhidmatan (Caruman / Pampasan / Perubatan).","Pengurusan barisan dan masa menunggu via sistem QMS.","Pengesahan dokumen pekerja di kaunter.","Penghantaran laporan harian ke Ibu Pejabat sebelum 5:00 petang.","Penutupan cawangan dan backup data pada 5:30 petang."]', 'SOP_Operasi_Cawangan.pdf', '940 KB', '1.4', 'Pengarah Bahagian Operasi', '2026-01-30T08:30:00Z', 'Aktif', NOW(), NOW());
INSERT INTO "Circular" ("id","circularNo","title","category","summary","content","fileName","fileSize","isMandatory","dateIssued","createdAt","updatedAt") VALUES ('cir000000000000000000000001', 'PKSO/CIR/2026/014', 'Pekeliling Kemas Kini Kadar Caruman Bulanan 2026', 'Korporat', 'Kadar caruman bulanan dikemas kini berkuat kuasa 1 Julai 2026.', 'Berkuat kuasa 1 Julai 2026, kadar caruman bulanan PERKESO dikemas kini mengikut jadual baru (Lampiran A). Semua majikan dikehendaki menggunakan kadar baru bagi semua caruman bulanan Julai 2026 dan seterusnya.', 'Pekeliling_014_2026.pdf', '1.5 MB', true, '2026-06-25T09:00:00Z', NOW(), NOW());
INSERT INTO "Circular" ("id","circularNo","title","category","summary","content","fileName","fileSize","isMandatory","dateIssued","createdAt","updatedAt") VALUES ('cir000000000000000000000002', 'PKSO/CIR/2026/013', 'Pekeliling Penambahbaikan Khidmat Kaunter', 'Operasi', 'Penambahbaikan SOP khidmat kaunter cawangan dengan masa tindak balas ≤ 15 minit.', 'Pekeliling ini menetapkan penambahbaikan khidmat kaunter PERKESO dengan masa tindak balas maksimum 15 minit dan sistem penilaian pelanggan selepas setiap urusan.', 'Pekeliling_013_2026.pdf', '1.1 MB', false, '2026-06-18T10:00:00Z', NOW(), NOW());
INSERT INTO "Circular" ("id","circularNo","title","category","summary","content","fileName","fileSize","isMandatory","dateIssued","createdAt","updatedAt") VALUES ('cir000000000000000000000003', 'PKSO/CIR/2026/012', 'Pekeliling Tatacara Penyimpanan Dokumen Digital', 'ICT', 'Tatacara penyimpanan dokumen digital mengikut polisi retention 7 tahun.', 'Pekeliling ini menetapkan tatacara penyimpanan dan pelupusan dokumen digital PERKESO mengikut polisi retention 7 tahun selaras dengan Akta Arkib Negara 2003.', 'Pekeliling_012_2026.pdf', '1.3 MB', true, '2026-06-10T09:00:00Z', NOW(), NOW());
INSERT INTO "Circular" ("id","circularNo","title","category","summary","content","fileName","fileSize","isMandatory","dateIssued","createdAt","updatedAt") VALUES ('cir000000000000000000000004', 'PKSO/CIR/2026/011', 'Pekeliling Penyelarasan Tuntutan Elaun Perjalanan', 'Kewangan', 'Tuntutan elaun perjalanan mestilah dikemukakan dalam tempoh 30 hari.', 'Mulai 1 Jun 2026, semua tuntutan elaun perjalanan mestilah dikemukakan dalam tempoh 30 hari dari tarikh perjalanan. Tuntutan lewat tidak akan diproses tanpa kelulusan Ketua Bahagian.', 'Pekeliling_011_2026.pdf', '980 KB', true, '2026-05-20T09:00:00Z', NOW(), NOW());
INSERT INTO "Circular" ("id","circularNo","title","category","summary","content","fileName","fileSize","isMandatory","dateIssued","createdAt","updatedAt") VALUES ('cir000000000000000000000005', 'PKSO/CIR/2026/010', 'Pekeliling Hari Bertema Korporat Bulanan', 'HR', 'Hari bertema korporat akan diadakan setiap hari Jumaat pertama setiap bulan.', 'Mulai Julai 2026, hari bertema korporat akan diadakan setiap hari Jumaat pertama setiap bulan. Tema akan diumumkan sebelum tarikh.', 'Pekeliling_010_2026.pdf', '640 KB', false, '2026-05-08T09:00:00Z', NOW(), NOW());
INSERT INTO "Circular" ("id","circularNo","title","category","summary","content","fileName","fileSize","isMandatory","dateIssued","createdAt","updatedAt") VALUES ('cir000000000000000000000006', 'PKSO/CIR/2026/009', 'Pekeliling Polisi Kerja Dalam Talian / WFH', 'HR', 'Polisi kerja dalam talian / WFH dikemas kini dengan pengukuhan protokol keselamatan.', 'Polisi kerja dalam talian / WFH dikemas kini meliputi protokol keselamatan siber, log masuk VPN, dan kekerapan pelaporan.', 'Pekeliling_009_2026.pdf', '1.2 MB', true, '2026-04-15T09:00:00Z', NOW(), NOW());
INSERT INTO "Circular" ("id","circularNo","title","category","summary","content","fileName","fileSize","isMandatory","dateIssued","createdAt","updatedAt") VALUES ('cir000000000000000000000007', 'PKSO/CIR/2026/008', 'Pekeliling Audit Dalaman Suku Tahunan', 'Operasi', 'Audit dalaman suku tahunan akan dijalankan di semua cawangan.', 'Pekeliling ini mengumumkan jadual audit dalaman suku tahunan di semua cawangan PERKESO bermula Q3 2026.', 'Pekeliling_008_2026.pdf', '890 KB', false, '2026-03-22T09:00:00Z', NOW(), NOW());
INSERT INTO "Faq" ("id","question","answer","category","tags","createdAt","updatedAt") VALUES ('faq000000000000000000000001', 'Berapakah kadar caruman PERKESO untuk pekerja?', 'Kadar caruman PERKESO ialah 1.75% daripada gaji bulanan pekerja, ditambah dengan 1.75% daripada majikan, menjadikan jumlah 3.5%. Kadar ini berkuat kuasa berkuat kuasa bagi semua pekerja swasta di Malaysia.', 'Caruman', '["kadar","caruman","1.75%"]', NOW(), NOW());
INSERT INTO "Faq" ("id","question","answer","category","tags","createdAt","updatedAt") VALUES ('faq000000000000000000000002', 'Bagaimana cara saya membuat tuntutan pampasan kemalangan kerja?', 'Anda boleh membuat tuntutan pampasan kemalangan kerja melalui langkah berikut: (1) Laporkan kemalangan kepada majikan dalam 48 jam, (2) Majikan mengemukakan Borang 21 ke cawangan PERKESO, (3) Pemeriksaan perubatan di klinik panel, (4) Tunggu pengesahan Lembaga Perubatan. Proses lengkap biasanya 7-14 hari kerja.', 'Pampasan', '["kemalangan","tuntutan","borang 21"]', NOW(), NOW());
INSERT INTO "Faq" ("id","question","answer","category","tags","createdAt","updatedAt") VALUES ('faq000000000000000000000003', 'Bagaimana untuk mendaftar pekerja baharu dalam sistem PERKESO?', 'Pendaftaran pekerja baharu boleh dilakukan melalui portal e-Perkeso (https://e-portal.perkeso.gov.my). Majikan perlu log masuk, pilih ''Pendaftaran Pekerja'', dan lengkapkan borang dengan maklumat pekerja. Proses pengesahan biasanya 3-5 hari kerja.', 'Permohonan', '["pendaftaran","pekerja baharu","e-Perkeso"]', NOW(), NOW());
INSERT INTO "Faq" ("id","question","answer","category","tags","createdAt","updatedAt") VALUES ('faq000000000000000000000004', 'Apakah yang harus saya lakukan jika terlupa kata laluan portal?', 'Jika anda terlupa kata laluan, klik pautan ''Terlupa Kata Laluan'' pada halaman log masuk. Sistem akan menghantar pautan set semula kata laluan ke e-mel berdaftar anda. Pautan sah selama 24 jam.', 'Sistem', '["kata laluan","log masuk","set semula"]', NOW(), NOW());
INSERT INTO "Faq" ("id","question","answer","category","tags","createdAt","updatedAt") VALUES ('faq000000000000000000000005', 'Di mana saya boleh dapatkan borang tuntutan dan dokumen rasmi PERKESO?', 'Semua borang rasmi PERKESO boleh dimuat turun dari modul SOP, modul Pekeliling, atau modul Akta dalam portal ini. Anda juga boleh menggunakan fungsi Carian Global untuk mencari dokumen tertentu.', 'Sistem', '["borang","dokumen","muat turun"]', NOW(), NOW());
INSERT INTO "Faq" ("id","question","answer","category","tags","createdAt","updatedAt") VALUES ('faq000000000000000000000006', 'Bagaimana saya tahu status tuntutan saya?', 'Anda boleh menyemak status tuntutan melalui portal e-Perkeso dengan log masuk dan klik ''Status Tuntutan''. Sistem akan memaparkan peringkat pemprosesan terkini, jangkaan masa, dan pegawai yang mengendali.', 'Pampasan', '["status","tuntutan","e-Perkeso"]', NOW(), NOW());
INSERT INTO "Faq" ("id","question","answer","category","tags","createdAt","updatedAt") VALUES ('faq000000000000000000000007', 'Apakah jenis penyakit yang dilindungi oleh Skim Insurans Pekerjaan?', 'Skim Insurans Pekerjaan (SIP) melindungi penyakit pekerjaan seperti penyakit kulit akibat bahan kimia, pendengaran terjejas akibat bunyi bising, dan penyakit paru-paru akibat habuk. Senarai penuh 39 penyakit pekerjaan boleh didapati dalam Jadual Akta 799.', 'Pampasan', '["penyakit","SIP","pekerjaan"]', NOW(), NOW());
INSERT INTO "Faq" ("id","question","answer","category","tags","createdAt","updatedAt") VALUES ('faq000000000000000000000008', 'Bagaimana cara mengemas kini maklumat peribadi dalam rekod PERKESO?', 'Pekerja boleh mengemas kini maklumat peribadi melalui portal e-Perkeso. Pilih ''Profil Saya'', klik ''Kemas Kini'', dan hantar permohonan. Kemas kini akan diambil tindakan dalam 3-5 hari kerja oleh cawangan berdekatan.', 'Sistem', '["profil","kemas kini","maklumat"]', NOW(), NOW());
INSERT INTO "Faq" ("id","question","answer","category","tags","createdAt","updatedAt") VALUES ('faq000000000000000000000009', 'Apakah skim pemulihan vokasional yang disediakan?', 'PERKESO menyediakan skim pemulihan vokasional bagi pekerja yang mengalami kecacatan akibat kemalangan kerja. Skim ini termasuk latihan semula, bantuan kerja, dan modifikasi tempat kerja. Permohonan melalui pegawai pampasan cawangan berdekatan.', 'Pampasan', '["pemulihan","vokasional","kecacatan"]', NOW(), NOW());
INSERT INTO "Faq" ("id","question","answer","category","tags","createdAt","updatedAt") VALUES ('faq000000000000000000000010', 'Bagaimana cara mengemukakan aduan mengenai khidmat PERKESO?', 'Aduan boleh dikemukakan melalui: (1) Borang Aduan di kaunter, (2) E-mel ke aduan@perkeso.gov.my, (3) Sistem Aduan Dalam Talian dalam portal e-Perkeso, atau (4) Hotline 1-300-22-8000. Setiap aduan akan menerima nombor rujukan untuk pengesanan.', 'Sistem', '["aduan","khidmat","hotline"]', NOW(), NOW());
INSERT INTO "Faq" ("id","question","answer","category","tags","createdAt","updatedAt") VALUES ('faq000000000000000000000011', 'Berapakah had maksimum pampasan kemalangan kerja?', 'Had maksimum pampasan bergantung pada jenis dan tahap kecederaan. Untuk kecacatan kekal, pampasan boleh mencecah sehingga RM70,000 (pencen ilat) atau bayaran jumlah pukul. Bagi kematian, tanggungan akan menerima pencemaran dan faedah penjagaan anak.', 'Pampasan', '["had","maksimum","pampasan"]', NOW(), NOW());
INSERT INTO "Faq" ("id","question","answer","category","tags","createdAt","updatedAt") VALUES ('faq000000000000000000000012', 'Apakah syarat kelayakan untuk menerima faedah PERKESO?', 'Pekerja layak menerima faedah PERKESO jika: (1) Bekerja di bawah kontrak perkhidmatan, (2) Berumur 16-80 tahun, (3) Membayar caruman bulanan secara berkala. Pekerja kontrak, sambilan, dan sementara juga dilindungi.', 'Caruman', '["kelayakan","syarat","faedah"]', NOW(), NOW());
